        IRealmAssetHelperStorageListener listener = Mockito.mock(IRealmAssetHelperStorageListener.class);
        Mockito.when(osUtil.getCurrentDbVersion(Mockito.any(Context.class), Mockito.anyString())).thenReturn(null);

